export const SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export type Size = (typeof SIZES)[number];
export const MAX_SEED = 2147483646;
export const BOARD_VERSION = 'np1';

export interface BoardDescription {
  readonly code: string;
  readonly size: Size;
  readonly seed: number;
}

export function isSize(value: unknown): value is Size {
  return SIZES.some(size => size === value);
}

export function parseBoardCode(code: unknown): BoardDescription | null {
  if (typeof code !== 'string') return null;
  const parts = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(code);
  if (!parts) return null;
  const size = Number(parts[1]);
  const seed = Number(parts[2]);
  if (!isSize(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;
  return Object.freeze({ code, size, seed });
}

export function boardCode(size: Size, seed: number): string {
  return `${BOARD_VERSION}-${size}-${seed}`;
}
import type { BoardDescription } from './boardCode.ts';

export const RANDOM_MODULUS = 2147483647;
const RANDOM_RANGE = RANDOM_MODULUS - 1;

export function nextRandomState(state: number): number {
  return (state * 16807) % RANDOM_MODULUS;
}

export function boundedDraw(state: number, possibilities: number): { state: number; value: number } {
  const limit = Math.floor(RANDOM_RANGE / possibilities) * possibilities;
  let next = nextRandomState(state);
  while (next - 1 >= limit) next = nextRandomState(next);
  return { state: next, value: (next - 1) % possibilities };
}

export function generateDeck(board: BoardDescription): readonly number[] {
  const deck = Array.from({ length: board.size ** 2 }, (_, index) => Math.floor(index / 2));
  let randomState = board.seed;
  for (let index = deck.length - 1; index > 0; index--) {
    const draw = boundedDraw(randomState, index + 1);
    randomState = draw.state;
    const atIndex = deck[index];
    const atDraw = deck[draw.value];
    if (atIndex === undefined || atDraw === undefined) throw new Error('Invalid shuffle index');
    deck[index] = atDraw;
    deck[draw.value] = atIndex;
  }
  return Object.freeze(deck);
}
import { parseBoardCode } from './boardCode.ts';
import type { BoardDescription } from './boardCode.ts';
import { generateDeck } from './deck.ts';

export const SELECTION_KIND = { closed: 'closed', one: 'one', mismatch: 'mismatch' } as const;
export type SelectionKind = (typeof SELECTION_KIND)[keyof typeof SELECTION_KIND];
export type Selection =
  | { readonly kind: typeof SELECTION_KIND.closed }
  | { readonly kind: typeof SELECTION_KIND.one; readonly index: number }
  | { readonly kind: typeof SELECTION_KIND.mismatch; readonly first: number; readonly second: number; readonly remainingMs: number };
export interface Board extends BoardDescription { readonly deck: readonly number[] }
export interface GameState {
  readonly board: Board;
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}
export const MISMATCH_MS = 800;
export const MAX_MOVES = 999999;
export const MAX_ELAPSED_MS = 359999999;
export const CLOSED: Selection = Object.freeze({ kind: SELECTION_KIND.closed });

export function createGame(code: string): GameState | null {
  const description = parseBoardCode(code);
  if (!description) return null;
  const board = Object.freeze({ ...description, deck: generateDeck(description) });
  return { board, matched: [], selection: CLOSED, moves: 0, elapsedMs: 0, started: false };
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length;
}

export function pairCount(state: GameState): number { return state.matched.length / 2; }

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.board.deck.length ||
      state.matched.includes(index) || isWon(state)) return state;
  switch (state.selection.kind) {
    case SELECTION_KIND.closed:
      return { ...state, started: true, selection: { kind: SELECTION_KIND.one, index } };
    case SELECTION_KIND.one: {
      const first = state.selection.index;
      if (first === index) return state;
      const moves = Math.min(MAX_MOVES, state.moves + 1);
      if (state.board.deck[first] === state.board.deck[index]) {
        return { ...state, moves, selection: CLOSED, matched: [...state.matched, first, index] };
      }
      return { ...state, moves, selection: {
        kind: SELECTION_KIND.mismatch, first, second: index, remainingMs: MISMATCH_MS,
      } };
    }
    case SELECTION_KIND.mismatch:
      return state;
  }
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isSafeInteger(milliseconds) || milliseconds <= 0 || !state.started || isWon(state)) return state;
  const elapsedMs = Math.min(MAX_ELAPSED_MS, state.elapsedMs + milliseconds);
  switch (state.selection.kind) {
    case SELECTION_KIND.closed:
    case SELECTION_KIND.one:
      return { ...state, elapsedMs };
    case SELECTION_KIND.mismatch: {
      const remainingMs = state.selection.remainingMs - milliseconds;
      const selection: Selection = remainingMs <= 0 ? CLOSED : { ...state.selection, remainingMs };
      return { ...state, elapsedMs, selection };
    }
  }
}

export function formatTime(elapsedMs: number): string {
  const seconds = Math.floor(elapsedMs / 1000);
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
}
import { hasExactKeys, isRecord, isSafeNonnegative } from './formatValidation.ts';
import { CLOSED, MISMATCH_MS, SELECTION_KIND } from './state.ts';
import type { GameState, Selection } from './state.ts';

export function isPosition(value: unknown, length: number): value is number {
  return isSafeNonnegative(value) && value < length;
}

export function decodeSelection(value: unknown, game: GameState, matched: readonly number[]): Selection | null {
  if (!isRecord(value)) return null;
  const eligible = (index: unknown): index is number => isPosition(index, game.board.deck.length) && !matched.includes(index);
  switch (value.kind) {
    case SELECTION_KIND.closed:
      return hasExactKeys(value, ['kind']) ? CLOSED : null;
    case SELECTION_KIND.one:
      return hasExactKeys(value, ['kind', 'index']) && eligible(value.index)
        ? { kind: SELECTION_KIND.one, index: value.index } : null;
    case SELECTION_KIND.mismatch:
      if (!hasExactKeys(value, ['kind', 'first', 'second', 'remainingMs']) ||
          !eligible(value.first) || !eligible(value.second) || value.first === value.second ||
          game.board.deck[value.first] === game.board.deck[value.second] ||
          !isSafeNonnegative(value.remainingMs) || value.remainingMs < 1 || value.remainingMs > MISMATCH_MS) return null;
      return { kind: SELECTION_KIND.mismatch, first: value.first, second: value.second, remainingMs: value.remainingMs };
    default:
      return null;
  }
}

export function decodeMatched(value: unknown, game: GameState): readonly number[] | null {
  if (!Array.isArray(value)) return null;
  const entries: readonly unknown[] = value;
  const matched: number[] = [];
  const faceCounts = new Map<number, number>();
  for (const index of entries) {
    if (!isPosition(index, game.board.deck.length) || matched.includes(index)) return null;
    const face = game.board.deck[index];
    if (face === undefined) return null;
    matched.push(index);
    faceCounts.set(face, (faceCounts.get(face) ?? 0) + 1);
  }
  return [...faceCounts.values()].every(count => count === 2) ? matched : null;
}
